import React from 'react';
import './styles.css';

const SEATS = ['A1', 'A2', 'A3', 'B1', 'B2', 'B3'];
const INITIAL_SOLD = ['A2'];

export default function App() {
  const soldSeats = INITIAL_SOLD;

  return (
    <main className="app">
      <h1>选座</h1>
      <div className="seat-grid">
        {SEATS.map((seat) => {
          const isSold = soldSeats.includes(seat);
          return (
            <button
              key={seat}
              type="button"
              data-testid={`seat-${seat}`}
              className={`seat ${isSold ? 'seat--sold' : ''}`}
              aria-disabled={isSold}
              onClick={() => {}}
            >
              <span className="seat__label">{seat}</span>
              {isSold && <span className="seat__status">已售</span>}
            </button>
          );
        })}
      </div>
    </main>
  );
}

