* { box-sizing: border-box; }

body { margin: 0; font-family: sans-serif; }

.app { padding: 24px; max-width: 100%; }

.seat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  max-width: 360px;
}

.seat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  padding: 12px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  background: #f8fafc;
  cursor: pointer;
  font-size: 14px;
}

.seat--sold {
  background: #e2e8f0;
  color: #94a3b8;
  cursor: not-allowed;
}

.seat__label { font-weight: 600; }

.seat__status { font-size: 12px; }
